CREATE OR REPLACE FUNCTION public.whiteboard_delete_project(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  result JSONB;
BEGIN
  DELETE FROM app.whiteboard_projects
  WHERE id = p_project_id
  AND student_id = auth.uid();

  result := jsonb_build_object(
    'success', true,
    'message', 'Project deleted'
  );

  RETURN result;
END;
$function$
